_APP_ICON_BYTES = None
_APP_ICON_PHOTO = None   # 持有 PhotoImage 引用，防止被 GC 回收后图标消失


def app_icon_bytes():
    """返回 ICO 二进制内容（懒解码，失败返回 None）。"""
    global _APP_ICON_BYTES
    if _APP_ICON_BYTES is None:
        try:
            _APP_ICON_BYTES = base64.b64decode(_ICON_B64)
        except Exception:
            _APP_ICON_BYTES = b""
    return _APP_ICON_BYTES or None


def app_icon_photos():
    """返回 [(尺寸, PhotoImage), ...]，取不到则空列表（Tk iconphoto 只认 PNG）。"""
    out = []
    for size in (16, 24, 32, 48, 64, 128, 256):
        b64 = globals().get("_ICON_PNG_%d" % size)
        if not b64:
            continue
        try:
            out.append((size, tk.PhotoImage(data=b64)))
        except tk.TclError:
            pass
    return out


def apply_window_icon(root):
    """设置窗口/任务栏图标：先从内嵌数据取，失败则退回同目录 app_icon.ico。"""
    global _APP_ICON_PHOTO
    photos = app_icon_photos()
    if photos:
        _APP_ICON_PHOTO = photos[-1][1]     # 保留最大尺寸引用防 GC
        try:
            root.iconphoto(True, *[p for _, p in photos])
            return True
        except tk.TclError:
            pass
    ico = os.path.join(SCRIPT_DIR, "app_icon.ico")
    if os.path.exists(ico):
        try:
            root.iconbitmap(default=ico)
            return True
        except tk.TclError:
            pass
    return False

