# ---------------------------------------------------------------- 路径自动检测

def detect_game_dir():
    """尝试自动定位 Apex 安装目录。"""
    candidates = []
    # 1. 解析 Steam libraryfolders.vdf 中的所有库路径
    steam_root = r"C:\Program Files (x86)\Steam"
    vdf = os.path.join(steam_root, "steamapps", "libraryfolders.vdf")
    libs = [steam_root]
    if os.path.isfile(vdf):
        try:
            with open(vdf, "r", encoding="utf-8", errors="replace") as f:
                for m in re.finditer(r'"path"\s+"([^"]+)"', f.read()):
                    p = m.group(1).replace("\\\\", "\\")
                    if p not in libs:
                        libs.append(p)
        except OSError:
            pass
    for lib in libs:
        candidates.append(os.path.join(lib, "steamapps", "common", "Apex Legends"))
    # 2. 常见备选位置
    candidates += [
        r"D:\Steam\steamapps\common\Apex Legends",
        r"D:\SteamLibrary\steamapps\common\Apex Legends",
        r"E:\SteamLibrary\steamapps\common\Apex Legends",
    ]
    for c in candidates:
        if os.path.isdir(os.path.join(c, "audio", "ship")):
            return c
    return ""


def detect_profile_cfg():
    p = os.path.join(
        os.environ.get("USERPROFILE", os.path.expanduser("~")),
        "Saved Games", "Respawn", "Apex", "profile", "profile.cfg",
    )
    return p if os.path.isfile(p) else ""


def load_app_config():
    cfg = {"game_dir": "", "profile_cfg": "", "backup_dir": os.path.join(SCRIPT_DIR, "voice_pack_backup")}
    # 首次运行时，把旧版本遗留在 exe 同目录的配置迁移过来（保住用户已填的路径）
    if not os.path.isfile(CONFIG_PATH) and os.path.isfile(LEGACY_CONFIG_PATH) \
            and os.path.abspath(LEGACY_CONFIG_PATH) != os.path.abspath(CONFIG_PATH):
        try:
            shutil.copy2(LEGACY_CONFIG_PATH, CONFIG_PATH)
        except OSError:
            pass
    if os.path.isfile(CONFIG_PATH):
        try:
            with open(CONFIG_PATH, "r", encoding="utf-8") as f:
                # 空值不覆盖默认/自动检测结果
                cfg.update({k: v for k, v in json.load(f).items() if k in cfg and v})
        except (OSError, ValueError):
            pass
    if not cfg.get("game_dir") or not os.path.isdir(cfg["game_dir"]):
        cfg["game_dir"] = detect_game_dir()
    if not cfg.get("profile_cfg") or not os.path.isfile(cfg["profile_cfg"]):
        cfg["profile_cfg"] = detect_profile_cfg()
    return cfg


def save_app_config(cfg):
    try:
        with open(CONFIG_PATH, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
    except OSError as e:
        print("保存配置失败:", e)


# ---------------------------------------------------------------- 核心逻辑

def resolve_ship_dir(path):
    """把用户填写的路径归一化到 audio\\ship 目录。

    兼容三种填法（用户实测踩过坑）：
      1) ...\\Apex Legends                  → 游戏根目录
      2) ...\\Apex Legends\\audio           → audio 目录
      3) ...\\Apex Legends\\audio\\ship     → 语音包目录本身
    """
    if not path or not os.path.isdir(path):
        return ""
    p = os.path.normpath(path)
    base = os.path.basename(p).lower()
    parent = os.path.basename(os.path.dirname(p)).lower()
    if base == "ship":                       # 已指向 ship
        return p
    if base == "audio":                      # 指向 audio
        cand = os.path.join(p, "ship")
        return cand if os.path.isdir(cand) else cand
    cand = os.path.join(p, "audio", "ship")  # 指向游戏根目录
    if os.path.isdir(cand):
        return cand
    # 兜底：该目录下直接就有语音包文件
    try:
        if any(MSTR_RE.match(n) for n in os.listdir(p)):
            return p
    except OSError:
        pass
    return cand


def ship_dir(game_dir):
    """兼容入口：返回实际使用的 audio\\ship 路径。"""
    return resolve_ship_dir(game_dir)


def guess_game_root(path):
    """由 audio\\ship（或 audio）反推游戏根目录；识别不了则原样返回。"""
    if not path:
        return ""
    p = os.path.normpath(path)
    if os.path.basename(p).lower() == "ship" and os.path.basename(os.path.dirname(p)).lower() == "audio":
        return os.path.dirname(os.path.dirname(p))
    if os.path.basename(p).lower() == "audio":
        return os.path.dirname(p)
    return p


def scan_installed_packs(game_dir):
    """返回 {lang: [文件绝对路径, ...]}，按语言聚合 audio\\ship 下的语音包。"""
    result = {}
    sd = ship_dir(game_dir)
    if not os.path.isdir(sd):
        return result
    for name in sorted(os.listdir(sd)):
        m = MSTR_RE.match(name)
        if not m:
            continue
        lang = m.group(1).lower()
        if lang in NON_LANGUAGE:
            continue
        result.setdefault(lang, []).append(os.path.join(sd, name))
    return result


def scan_backup_packs(backup_dir):
    result = {}
    if not os.path.isdir(backup_dir):
        return result
    for name in sorted(os.listdir(backup_dir)):
        m = MSTR_RE.match(name)
        if not m:
            continue
        lang = m.group(1).lower()
        if lang in NON_LANGUAGE:
            continue
        result.setdefault(lang, []).append(os.path.join(backup_dir, name))
    return result


def read_cfg_text(path):
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
        return f.read()


def _clear_readonly(path):
    """文件存在且为只读时，临时清除只读属性。返回是否原本只读。"""
    if os.path.isfile(path) and not os.access(path, os.W_OK):
        try:
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
            return True
        except OSError:
            return False
    return False


def _restore_readonly(path, was_readonly):
    """恢复原有只读属性（保持用户环境不变）。"""
    if was_readonly:
        try:
            os.chmod(path, stat.S_IREAD)
        except OSError:
            pass


def write_cfg_text(path, text):
    was_ro = _clear_readonly(path)
    try:
        with open(path, "w", encoding="utf-8", errors="surrogateescape") as f:
            f.write(text)
    finally:
        _restore_readonly(path, was_ro)


def get_current_voice(cfg_path):
    """返回 cfg 中 miles_language 的值；未设置返回 None。"""
    if not cfg_path or not os.path.isfile(cfg_path):
        return None
    m = re.search(r'^\s*miles_language\s+"?([A-Za-z]+)"?\s*$', read_cfg_text(cfg_path), re.MULTILINE)
    return m.group(1).lower() if m else None


def has_empty_voice_setting(cfg_path):
    """检测是否存在 miles_language ""（空值）：该值会导致配音加载异常，需修复。"""
    if not cfg_path or not os.path.isfile(cfg_path):
        return False
    return re.search(r'^\s*miles_language\s*""\s*$', read_cfg_text(cfg_path), re.MULTILINE) is not None


def _no_window_kwargs():
    """让子进程不弹出黑色控制台窗口（Windows）。"""
    if os.name == "nt":
        return {"creationflags": 0x08000000}  # CREATE_NO_WINDOW
    return {}


def _process_names():
    """枚举当前进程名集合。优先用 Win32 API（不创建任何窗口、无闪烁），失败才退回 tasklist。"""
    names = set()
    if os.name == "nt":
        try:
            import ctypes
            from ctypes import wintypes

            TH32CS_SNAPPROCESS = 0x00000002

            class PROCESSENTRY32(ctypes.Structure):
                _fields_ = [
                    ("dwSize", wintypes.DWORD),
                    ("cntUsage", wintypes.DWORD),
                    ("th32ProcessID", wintypes.DWORD),
                    ("th32DefaultHeapID", ctypes.POINTER(ctypes.c_ulong)),
                    ("th32ModuleID", wintypes.DWORD),
                    ("cntThreads", wintypes.DWORD),
                    ("th32ParentProcessID", wintypes.DWORD),
                    ("pcPriClassBase", ctypes.c_long),
                    ("dwFlags", wintypes.DWORD),
                    ("szExeFile", ctypes.c_char * 260),
                ]

            k32 = ctypes.windll.kernel32
            snap = k32.CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0)
            if snap and snap != -1:
                try:
                    entry = PROCESSENTRY32()
                    entry.dwSize = ctypes.sizeof(PROCESSENTRY32)
                    ok = k32.Process32First(snap, ctypes.byref(entry))
                    while ok:
                        names.add(entry.szExeFile.decode("mbcs", "ignore").lower())
                        ok = k32.Process32Next(snap, ctypes.byref(entry))
                finally:
                    k32.CloseHandle(snap)
                return names
        except Exception:  # noqa: BLE001
            pass
    # 兜底：tasklist（带 CREATE_NO_WINDOW，同样不闪窗）
    try:
        out = subprocess.run(["tasklist", "/NH"], capture_output=True, text=True,
                             encoding="gbk", errors="replace", timeout=10,
                             **_no_window_kwargs()).stdout or ""
        for line in out.splitlines():
            parts = line.split()
            if parts:
                names.add(parts[0].strip('"').lower())
    except (OSError, subprocess.TimeoutExpired):
        pass
    return names


def is_game_running():
    """检测 Apex 是否在运行（纯 API 查询，无窗口、无闪烁）。"""
    names = _process_names()
    return "r5apex.exe" in names or "r5apex_dx12.exe" in names


def is_steam_running():
    """检测 Steam 是否在运行（纯 API 查询，无窗口、无闪烁）。"""
    return "steam.exe" in _process_names()


def backup_profile_cfg(cfg_path):
    bak = cfg_path + CFG_BACKUP_SUFFIX
    _clear_readonly(bak)  # 旧备份可能带只读属性，先解除再覆盖
    shutil.copy2(cfg_path, bak)
    return bak


def set_miles_language(cfg_path, lang):
    """写入/替换 miles_language 行。返回 (ok, message)。"""
    if not cfg_path or not os.path.isfile(cfg_path):
        return False, "找不到 profile.cfg，请手动指定路径"
    if is_game_running():
        return False, "游戏正在运行，请先完全退出 Apex 再切换"
    bak = backup_profile_cfg(cfg_path)
    text = read_cfg_text(cfg_path)
    line = f'miles_language "{lang}"'
    pattern = re.compile(rf'^\s*miles_language\s+"?{re.escape(lang)}"?\s*$', re.MULTILINE)
    if pattern.search(text):
        pass  # 目标已是该语言
    elif re.search(r"^\s*miles_language\s+", text, re.MULTILINE):
        text = re.sub(r"^\s*miles_language\s+.*$", line, text, count=1, flags=re.MULTILINE)
    else:
        if not text.endswith("\n"):
            text += "\n"
        text += line + "\n"
    write_cfg_text(cfg_path, text)
    extra = write_lang_to_settings_cfg(lang)
    msg = f'已写入 miles_language "{lang}"（profile.cfg，原配置已备份为 {os.path.basename(bak)}）'
    if extra:
        msg += "；并已写入当前版本设置文件 Local\\settings.cfg"
    msg += '。配音语言在游戏启动时读取 → 请重启游戏，推荐直接用「启动游戏（带所选配音）」按钮。'
    return True, msg


def remove_miles_language(cfg_path):
    """删除 miles_language 行，恢复跟随界面语言。"""
    if not cfg_path or not os.path.isfile(cfg_path):
        return False, "找不到 profile.cfg"
    if is_game_running():
        return False, "游戏正在运行，请先完全退出 Apex 再操作"
    bak = backup_profile_cfg(cfg_path)
    text = re.sub(r"^\s*miles_language\s+.*$\n?", "", read_cfg_text(cfg_path), flags=re.MULTILINE)
    write_cfg_text(cfg_path, text)
    # 同步清理当前版本的设置文件
    sp = settings_cfg_path()
    if sp:
        try:
            st = re.sub(r"^\s*miles_language\s+.*$\n?", "", read_cfg_text(sp), flags=re.MULTILINE)
            write_cfg_text(sp, st)
        except OSError:
            pass
    return True, f"已恢复默认（跟随界面语言）。原配置备份于 {os.path.basename(bak)}"


def restore_pack_from_backup(lang, game_dir, backup_dir):
    """把备份库中某语言的语音包复制回 audio\\ship。返回恢复的文件数。"""
    files = scan_backup_packs(backup_dir).get(lang, [])
    if not files:
        return 0
    sd = ship_dir(game_dir)
    os.makedirs(sd, exist_ok=True)
    n = 0
    for src in files:
        dst = os.path.join(sd, os.path.basename(src))
        shutil.copy2(src, dst)
        n += 1
    return n


def export_packs_to_backup(game_dir, backup_dir, langs=None, progress=None):
    """把游戏目录中的语音包复制到备份库。

    langs=None 表示全部语言；否则只复制指定语言集合（如 {"japanese", "english"}）。
    返回 (copied, skipped, failed, total_bytes)。
    """
    os.makedirs(backup_dir, exist_ok=True)
    available = scan_installed_packs(game_dir)
    copied, skipped, failed = [], [], []
    total = 0
    for lang, files in sorted(available.items()):
        if langs is not None and lang not in langs:
            continue
        for src in files:
            name = os.path.basename(src)
            dst = os.path.join(backup_dir, name)
            try:
                size = os.path.getsize(src)
                if os.path.isfile(dst) and os.path.getsize(dst) == size:
                    skipped.append(name)
                    if progress:
                        progress(f"跳过（已存在）{name}")
                    continue
                total += size
                if progress:
                    progress(f"复制 {name}（{size / 1024 / 1024 / 1024:.2f} GB）…")
                _clear_readonly(dst)
                shutil.copy2(src, dst)
                copied.append(name)
            except OSError as e:
                failed.append(f"{name}: {e}")
                if progress:
                    progress(f"失败 {name}：{e}")
    return copied, skipped, failed, total


def selected_size(game_dir, langs):
    """统计所选语言包的总字节数（用于磁盘空间预检）。"""
    packs = scan_installed_packs(game_dir)
    total = 0
    for lang in langs:
        for f in packs.get(lang, []):
            try:
                total += os.path.getsize(f)
            except OSError:
                pass
    return total


def _steam_localconfig_paths():
    """所有可能存放 Apex 启动项的 Steam 配置文件路径。"""
    steam_exe = find_steam_exe()
    root_dir = os.path.dirname(steam_exe) if steam_exe else r"C:\Program Files (x86)\Steam"
    paths = [os.path.join(root_dir, "config", "localconfig.vdf")]
    paths += glob.glob(os.path.join(root_dir, "userdata", "*", "config", "localconfig.vdf"))
    return [p for p in paths if os.path.isfile(p)]


def parse_pinned_languages(raw):
    """从 Steam 配置文本中解析 Apex 启动项固定的配音语言集合（纯函数，便于自检）。"""
    opts = extract_apex_launch_options(raw)
    if not opts:
        return set()
    return {m.group(1).lower() for m in re.finditer(r"\+miles_language\s+([A-Za-z]+)", opts)}


def _read_pinned_languages_detailed():
    """返回 (pinned, ok)。ok=False 表示暂时读不到 Apex 段落（例如 Steam 正在重写配置），
    此时调用方应保持上一次的显示状态，避免界面闪烁。"""
    pinned = set()
    ok = False
    for p in _steam_localconfig_paths():
        try:
            with open(p, "r", encoding="utf-8", errors="replace") as f:
                raw = f.read()
        except OSError:
            continue
        opts = extract_apex_launch_options(raw)
        if opts is None:
            continue
        ok = True
        for m in re.finditer(r"\+miles_language\s+([A-Za-z]+)", opts):
            pinned.add(m.group(1).lower())
    return pinned, ok


def get_pinned_launch_languages():
    """读取 Steam 启动项中固定的配音语言（可能来自多个 Steam 账号配置）。"""
    return _read_pinned_languages_detailed()[0]


def find_steam_launch_warnings(steam_dir_candidates):
    """检查指定 Steam 目录下是否含 miles_language（仅扫描传入路径，保持可离线自检）。"""
    hits = []
    for root in steam_dir_candidates or []:
        if not root or not os.path.isdir(root):
            continue
        for p in [os.path.join(root, "config", "localconfig.vdf")] + \
                glob.glob(os.path.join(root, "userdata", "*", "config", "localconfig.vdf")):
            if not os.path.isfile(p):
                continue
            try:
                with open(p, "r", encoding="utf-8", errors="replace") as f:
                    if "miles_language" in f.read():
                        hits.append(p)
            except OSError:
                pass
    return hits


def settings_cfg_path():
    """当前版本 Apex 的实际设置文件：Saved Games\\Respawn\\Apex\\local\\settings.cfg。"""
    base = os.path.join(
        os.environ.get("USERPROFILE", os.path.expanduser("~")),
        "Saved Games", "Respawn", "Apex", "local",
    )
    p = os.path.join(base, "settings.cfg")
    return p if os.path.isfile(p) else ""


def write_lang_to_settings_cfg(lang, path=None):
    """把 miles_language 写入 local\\settings.cfg（当前版本的设置文件）。返回路径或 None。

    注意：该文件由游戏在退出时重写，写入的值可能被游戏覆盖，因此仅作辅助手段；
    真正可靠的机制是启动参数 +miles_language（见 launch_game）。
    """
    p = path or settings_cfg_path()
    if not p or not os.path.isfile(p):
        return None
    try:
        bak = p + CFG_BACKUP_SUFFIX
        if not os.path.isfile(bak):
            shutil.copy2(p, bak)
        text = read_cfg_text(p)
        line = f'miles_language "{lang}"'
        if re.search(r"^\s*miles_language\s+", text, re.MULTILINE):
            text = re.sub(r"^\s*miles_language\s+.*$", line, text, count=1, flags=re.MULTILINE)
        else:
            if not text.endswith("\n"):
                text += "\n"
            text += line + "\n"
        write_cfg_text(p, text)
        return p
    except OSError:
        return None


def find_steam_exe():
    """定位 steam.exe（优先读注册表，其次常见路径）。"""
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Valve\Steam") as k:
            v = winreg.QueryValueEx(k, "SteamExe")[0]
            if v:
                v = v.replace("/", "\\")
                if os.path.isfile(v):
                    return v
    except Exception:  # noqa: BLE001
        pass
    for p in (r"C:\Program Files (x86)\Steam\steam.exe", r"D:\Steam\steam.exe",
              r"D:\SteamLibrary\steam.exe"):
        if os.path.isfile(p):
            return p
    return ""


def launch_game(lang=None):
    """启动 Apex。lang 非空时附带 +miles_language 参数（配音语言在启动时读取）。

    这样无需修改 Steam 启动项、无需重启 Steam，也能即时切换配音。
    返回说明文本；失败抛异常。
    """
    steam_exe = find_steam_exe()
    if steam_exe:
        cmd = [steam_exe, "-applaunch", STEAM_APPID]
        if lang:
            cmd += ["+miles_language", lang]
        subprocess.Popen(cmd, **_no_window_kwargs())  # noqa: S603
        return ("已通过 Steam 启动（配音参数：+miles_language " + lang + "）"
                if lang else "已通过 Steam 启动（未附带配音参数）")
    os.startfile(f"steam://rungameid/{STEAM_APPID}")  # noqa: S606
    return "已通过 steam:// 协议启动（未附带配音参数）"


def find_steam_localconfig():
    """定位含 Apex 配置的 Steam localconfig.vdf。"""
    steam_exe = find_steam_exe()
    steam_root = os.path.dirname(steam_exe) if steam_exe else r"C:\Program Files (x86)\Steam"
    cands = [os.path.join(steam_root, "config", "localconfig.vdf")]
    cands += glob.glob(os.path.join(steam_root, "userdata", "*", "config", "localconfig.vdf"))
    for p in cands:
        if os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8", errors="replace") as f:
                    if '"1172470"' in f.read():
                        return p
            except OSError:
                pass
    return ""


def extract_apex_launch_options(raw):
    """从 localconfig.vdf 文本中取出 Apex 段落的 LaunchOptions 值；取不到返回 None。"""
    for m in re.finditer(r'"1172470"', raw):
        if "{" in raw[m.end():m.end() + 40]:
            window = raw[m.end():m.end() + 3000]
            mo = re.search(r'"LaunchOptions"\s+"([^"]*)"', window)
            return mo.group(1) if mo else None
    return None


def _apply_launch_option(raw, lang):
    """在 Steam localconfig.vdf 文本中，为 Apex 段落写入 +miles_language <lang>。

    返回 (new_text, old_options, error)。纯函数，便于自检与离线验证。
    """
    m_app = None
    for m in re.finditer(r'"1172470"', raw):
        if "{" in raw[m.end():m.end() + 40]:
            m_app = m
            break
    if not m_app:
        return raw, "", "未在 Steam 配置中找到 Apex 的配置段落。"
    seg_start = m_app.end()
    window = raw[seg_start:seg_start + 3000]
    m_lo = re.search(r'"LaunchOptions"\s+"([^"]*)"', window)
    if not m_lo:
        return raw, "", "Apex 段落中没有找到 LaunchOptions 字段（请先在 Steam 里设置一次启动项再试）。"
    old = m_lo.group(1)
    lang_words = ("japanese", "english", "mandarin", "korean", "french", "german", "spanish",
                  "italian", "russian", "polish", "portuguese", "mexican", "tchinese")
    parts = [t for t in old.split()
             if t.lower() != "+miles_language" and t.lower() not in lang_words]
    parts.append(f"+miles_language {lang}")
    new = " ".join(parts)
    new_raw = raw[:seg_start + m_lo.start(1)] + new + raw[seg_start + m_lo.end(1):]
    return new_raw, old, ""


def set_steam_launch_option(lang):
    """把 +miles_language <lang> 写进 Steam 启动项（需完全退出 Steam）。

    仅替换 Apex(1172470) 段落内 LaunchOptions 中的 miles_language 片段，其余参数保持不动。
    返回 (ok, message)。
    """
    if is_steam_running():
        return False, "请先完全退出 Steam（右下角托盘右键退出）再操作。"
    path = find_steam_localconfig()
    if not path:
        return False, "未找到 Steam 的 localconfig.vdf。"
    try:
        raw = open(path, "r", encoding="utf-8", errors="replace").read()
    except OSError as e:
        return False, f"读取 Steam 配置失败：{e}"

    new_raw, old, err = _apply_launch_option(raw, lang)
    if err:
        return False, err

    bak = path + CFG_BACKUP_SUFFIX
    try:
        if not os.path.isfile(bak):
            shutil.copy2(path, bak)
        with open(path, "w", encoding="utf-8", errors="surrogateescape") as f:
            f.write(new_raw)
    except OSError as e:
        return False, f"写入 Steam 配置失败：{e}"
    new = extract_apex_launch_options(new_raw) or ""
    return True, f"已写入 Steam 启动项：{new}\n（原配置备份于 {os.path.basename(bak)}）"


def lang_display(lang):
    return LANG_NAMES.get(lang, lang)


# ---------------------------------------------------------------- 自检

def selftest():
    """无 GUI 逻辑自检：构造临时目录验证核心函数。"""
    import tempfile
    ok = True

    def check(name, cond):
        nonlocal ok
        print(("PASS" if cond else "FAIL"), "-", name)
        ok = ok and cond

    with tempfile.TemporaryDirectory() as tmp:
        game = os.path.join(tmp, "Apex Legends")
        sd = os.path.join(game, "audio", "ship")
        os.makedirs(sd)
        cfg = os.path.join(tmp, "profile.cfg")
        bak_dir = os.path.join(tmp, "backup")
        with open(cfg, "w", encoding="utf-8") as f:
            f.write('cl_fovScale "1.55"\nclosecaption "1"\n')
        # 假语音包
        for fn in ("general_english.mstr", "general_english_patch_1.mstr",
                   "general_mandarin.mstr", "general_stream.mstr",
                   "general_japanese.mstr", "general_japanese_patch_1.mstr"):
            with open(os.path.join(sd, fn), "wb") as f:
                f.write(b"fake")

        packs = scan_installed_packs(game)
        check("扫描语言包(排除stream)", sorted(packs) == ["english", "japanese", "mandarin"])

        b, msg = set_miles_language(cfg, "japanese")
        check("写入miles_language", b and get_current_voice(cfg) == "japanese")
        check("写入后保留原有配置", 'cl_fovScale "1.55"' in read_cfg_text(cfg))
        check("自动生成备份", os.path.isfile(cfg + CFG_BACKUP_SUFFIX))

        b, _ = set_miles_language(cfg, "english")
        check("替换已有行", b and get_current_voice(cfg) == "english")

        b, _ = remove_miles_language(cfg)
        check("删除行恢复默认", b and get_current_voice(cfg) is None)

        # 空值 miles_language "" 的识别与修复
        with open(cfg, "a", encoding="utf-8") as f:
            f.write('miles_language ""\n')
        check("识别空值配置", get_current_voice(cfg) is None and has_empty_voice_setting(cfg))
        b, _ = set_miles_language(cfg, "japanese")
        check("空值可被替换为有效语言", b and get_current_voice(cfg) == "japanese"
              and not has_empty_voice_setting(cfg))
        with open(cfg, "a", encoding="utf-8") as f:
            f.write('miles_language ""\n')
        b, _ = remove_miles_language(cfg)
        check("空值可被清除", b and not has_empty_voice_setting(cfg) and get_current_voice(cfg) is None)

        # 只读属性处理（真实环境遇到过 profile.cfg 被设为只读）
        os.chmod(cfg, stat.S_IREAD)
        b, _ = set_miles_language(cfg, "japanese")
        check("只读配置文件可正常写入", b and get_current_voice(cfg) == "japanese")
        check("只读属性被完整保留", not os.access(cfg, os.W_OK))
        os.chmod(cfg, stat.S_IWRITE | stat.S_IREAD)

        # 路径兼容性：游戏根目录 / audio / audio\ship 三种填法都要能识别
        check("路径兼容-游戏根目录", resolve_ship_dir(game) == os.path.normpath(sd))
        check("路径兼容-audio 目录", resolve_ship_dir(os.path.join(game, "audio")) == os.path.normpath(sd))
        check("路径兼容-audio\\ship 目录", resolve_ship_dir(sd) == os.path.normpath(sd))
        check("由 ship 反推游戏根目录", guess_game_root(sd) == game)

        # 按勾选导出（用户实测需求：只备份选中的语言）
        copied, skipped, failed, _ = export_packs_to_backup(game, bak_dir, langs={"japanese"})
        check("按勾选备份(仅日语 2 文件)", len(copied) == 2 and not failed and not skipped)
        copied_all, skipped_all, failed_all, _ = export_packs_to_backup(game, bak_dir)
        check("全量备份(新增 3 个 / 跳过已备份 2 个)",
              len(copied_all) == 3 and len(skipped_all) == 2 and not failed_all)
        copied2, skipped2, _, _ = export_packs_to_backup(game, bak_dir)
        check("重复导入跳过", not copied2 and len(skipped2) == 5)

        for fn in os.listdir(sd):
            if "japanese" in fn:
                os.remove(os.path.join(sd, fn))
        n = restore_pack_from_backup("japanese", game, bak_dir)
        check("从备份恢复日语包", n == 2 and "general_japanese.mstr" in os.listdir(sd))

        warnings = find_steam_launch_warnings([tmp])  # tmp 下无 vdf，应为空
        check("启动项检查(无异常)", warnings == [])

        # 当前版本设置文件 local\settings.cfg 的写入
        scfg = os.path.join(tmp, "settings.cfg")
        with open(scfg, "w", encoding="utf-8") as f:
            f.write('bind_US_standard "w" "+forward" 0\nsound_volume_voice "1"\n')
        p = write_lang_to_settings_cfg("japanese", path=scfg)
        check("settings.cfg 写入成功", p == scfg and 'miles_language "japanese"' in read_cfg_text(scfg))
        check("settings.cfg 原有内容保留", 'bind_US_standard "w" "+forward" 0' in read_cfg_text(scfg))
        write_lang_to_settings_cfg("english", path=scfg)
        txt = read_cfg_text(scfg)
        check("settings.cfg 替换不重复", txt.count("miles_language") == 1 and '"english"' in txt)

        # Steam 启动项文本改写（纯函数，离线可验证）
        vdf = ('"Software"\n{\n\t"Valve"\n\t{\n\t\t"apps"\n\t\t{\n'
               '\t\t\t"1172470"\n\t\t\t{\n\t\t\t\t"LaunchOptions"\t\t"-novid +fps_max 159"\n\t\t\t}\n'
               '\t\t\t"1182480"\n\t\t\t{\n\t\t\t\t"Playtime"\t\t"3"\n\t\t\t}\n\t\t}\n\t}\n}\n')
        new_vdf, old, err = _apply_launch_option(vdf, "japanese")
        check("启动项写入(保留其它参数)",
              not err and old == "-novid +fps_max 159"
              and '"LaunchOptions"\t\t"-novid +fps_max 159 +miles_language japanese"' in new_vdf)
        new_vdf2, _, err2 = _apply_launch_option(new_vdf, "english")
        check("启动项切换不累积参数",
              not err2 and new_vdf2.count("+miles_language") == 1
              and "+miles_language english" in new_vdf2 and "japanese" not in new_vdf2)
        _, _, err3 = _apply_launch_option('"apps"\n{\n\t"999999"\n\t{\n\t}\n}\n', "japanese")
        check("找不到段落时安全报错", bool(err3))
        check("提取启动项内容",
              extract_apex_launch_options(new_vdf) == "-novid +fps_max 159 +miles_language japanese")
        check("无 Apex 段落时提取返回 None",
              extract_apex_launch_options('"apps"\n{\n\t"999999"\n\t{\n\t}\n}\n') is None)
        check("解析启动项固定语言", parse_pinned_languages(new_vdf) == {"japanese"})
        check("无启动项时固定语言为空",
              parse_pinned_languages('"apps"\n{\n\t"999999"\n\t{\n\t}\n}\n') == set())

    # 图标资源：内嵌 base64 必须能还原成合法 ICO（否则窗口/任务栏无图标）
    _ico = app_icon_bytes()
    check("应用图标已内嵌", bool(_ico))
    check("图标为合法ICO", bool(_ico) and _ico[:4] == b"\x00\x00\x01\x00")
    if _ico and len(_ico) >= 6:
        import struct
        _n_img = struct.unpack("<H", _ico[4:6])[0]
        check("图标含多尺寸(>=7张)", _n_img >= 7)

    # 防伪标记：明文与混淆串必须完整（防盗用/滥用）
    check("防伪标记(明文)完整",
          all(k in ANTI_FAKE_PLAIN for k in (MARK_OWNER, MARK_OWNER_ID, MARK_BRAND, MARK_BRAND_ID)))
    check("防伪标记(混淆串)校验通过", verify_anti_fake())

    print("SELFTEST", "PASSED" if ok else "FAILED")
    return ok


# ---------------------------------------------------------------- 系统剪贴板

def copy_text_to_clipboard(text):
    """复制文本到系统剪贴板（Win32 CF_UNICODETEXT）。

    与 Tk 内置 clipboard 的区别：程序退出后剪贴板内容仍然保留
    （Tk 剪贴板的所有权随进程结束而失效，复制后立刻关程序会丢失内容）。
    返回是否成功；失败时调用方应回退到 Tk clipboard。
    """
    try:
        import ctypes
        u32 = ctypes.WinDLL("user32")
        k32 = ctypes.WinDLL("kernel32")
        u32.OpenClipboard.argtypes = [ctypes.c_void_p]
        u32.SetClipboardData.argtypes = [ctypes.c_uint, ctypes.c_void_p]
        u32.SetClipboardData.restype = ctypes.c_void_p
        k32.GlobalAlloc.argtypes = [ctypes.c_uint, ctypes.c_size_t]
        k32.GlobalAlloc.restype = ctypes.c_void_p
        k32.GlobalLock.argtypes = [ctypes.c_void_p]
        k32.GlobalLock.restype = ctypes.c_void_p
        k32.GlobalUnlock.argtypes = [ctypes.c_void_p]
        k32.GlobalFree.argtypes = [ctypes.c_void_p]
        if not u32.OpenClipboard(None):
            return False
        try:
            u32.EmptyClipboard()
            buf = ctypes.create_unicode_buffer(text)
            size = ctypes.sizeof(buf)                       # 含结尾 NUL（UTF-16 字节数）
            h = k32.GlobalAlloc(0x0002, size)               # GMEM_MOVEABLE
            if not h:
                return False
            p = k32.GlobalLock(h)
            if not p:
                k32.GlobalFree(h)
                return False
            ctypes.memmove(p, buf, size)
            k32.GlobalUnlock(h)
            if not u32.SetClipboardData(13, h):             # CF_UNICODETEXT
                k32.GlobalFree(h)
                return False
            return True                                     # 成功后内存归剪贴板所有，勿再释放
        finally:
            u32.CloseClipboard()
    except Exception:  # noqa: BLE001
        return False


# ---------------------------------------------------------------- 高 DPI 适配

def enable_dpi_awareness():
    """声明进程 DPI 感知：避免在缩放 >100% 的屏幕上被系统位图拉伸导致发虚。"""
    try:
        import ctypes
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(1)  # SYSTEM_DPI_AWARE (Win8.1+)
        except (AttributeError, OSError):
            ctypes.windll.user32.SetProcessDPIAware()
    except Exception:  # noqa: BLE001
        pass


def system_scaling():
    """返回系统缩放系数（1.0 = 100%，1.5 = 150%，2.0 = 200%）。"""
    dpi = 96
    try:
        import ctypes
        dpi = int(ctypes.windll.user32.GetDpiForSystem())
    except Exception:  # noqa: BLE001
        try:
            import ctypes
            hdc = ctypes.windll.user32.GetDC(0)
            dpi = int(ctypes.windll.gdi32.GetDeviceCaps(hdc, 88))  # LOGPIXELSX
            ctypes.windll.user32.ReleaseDC(0, hdc)
        except Exception:  # noqa: BLE001
            dpi = 96
    if dpi <= 0:
        dpi = 96
    return dpi / 96.0


def apply_tk_scaling(root, scale):
    """让 Tk 的字体/控件按显示器缩放渲染（避免 4K 下文字过小或被拉伸模糊）。"""
    try:
        root.tk.call("tk", "scaling", max(1.0, scale) * 96.0 / 72.0)
    except tk.TclError:
        pass


def animations_enabled():
    """读取 Windows「在 Windows 中显示动画」无障碍设置（SPI_GETCLIENTAREAANIMATION）。

    用户关闭系统动画时跳过淡入等动效（对应 Apple「减弱动态效果」的尊重策略）。
    查询失败时默认开启动效。
    """
    try:
        val = ctypes.c_int(1)
        SPI_GETCLIENTAREAANIMATION = 0x1042
        if ctypes.windll.user32.SystemParametersInfoW(SPI_GETCLIENTAREAANIMATION, 0, ctypes.byref(val), 0):
            return bool(val.value)
    except Exception:  # noqa: BLE001  非 Windows / API 不可用 → 默认开启
        pass
    return True


def fade_in(root, duration_ms=180):
    """窗口淡入（ease-out cubic，180ms）：一次性、可被打断不留残影；减弱动效时直接显示。"""
    if not animations_enabled():
        return
    try:
        root.attributes("-alpha", 0.0)
    except tk.TclError:
        return
    t0 = time.perf_counter()
    dur = max(0.05, duration_ms / 1000.0)

    def _tick():
        try:
            p = min(1.0, (time.perf_counter() - t0) / dur)
            eased = 1.0 - (1.0 - p) ** 3          # ease-out cubic：起步快、收尾缓
            root.attributes("-alpha", eased)
            if p < 1.0:
                root.after(15, _tick)
            else:
                root.attributes("-alpha", 1.0)
        except tk.TclError:
            pass

    _tick()


class RoundedButton(tk.Canvas):
    """Apple 风格胶囊按钮（Canvas 自绘，tkinter 原生按钮无法圆角）。

    交互遵循 Apple「按下即反馈」：ButtonPress 瞬间变色，抬起时如果在按钮上才触发命令；
    悬停有轻微明暗变化；禁用态整体降透明感。kind：primary（蓝底白字）/ secondary（浅灰底深字）。
    """

    KINDS = {
        "primary":   dict(bg=BLUE, hover=BLUE_HOVER, press=BLUE_PRESS,
                          fg="#ffffff", disabled_bg=BLUE_DISABLED, disabled_fg="#f2f6fc"),
        "secondary": dict(bg=GRAY_BTN, hover=GRAY_BTN_HOVER, press=GRAY_BTN_PRESS,
                          fg=TEXT1, disabled_bg="#f0f0f2", disabled_fg="#b4b4bb"),
    }

    def __init__(self, master, text="", command=None, kind="secondary", scale=1.0,
                 height=28, padding_x=16, state="normal", font_size=10):
        self.scale = scale
        h = max(22, int(height * scale))
        self._kind = kind if kind in self.KINDS else "secondary"
        self._colors = self.KINDS[self._kind]
        self._text = text
        self._command = command
        self._state = state if state in ("normal", "disabled") else "normal"
        self._hover = False
        self._pressed = False
        self._font = tkfont.Font(family=FONT_FAMILY, size=font_size)
        w = self._font.measure(text) + int(padding_x * 2 * scale)
        # 宿主底色：tk 控件直接取；ttk 控件没有 background 选项，按 style 名推断
        try:
            mbg = master.cget("background")
        except (tk.TclError, AttributeError):
            try:
                st = str(master.cget("style") or "")
            except (tk.TclError, AttributeError):
                st = ""
            mbg = WIN_BG if "Bg." in st else CARD_BG
        super().__init__(master, width=w, height=h, highlightthickness=0, bd=0, background=mbg)
        self._radius = h // 2
        self._draw()
        # 按下即反馈：Press 立刻变色，Release 判定是否在按钮内触发
        self.bind("<ButtonPress-1>", self._on_press)
        self.bind("<ButtonRelease-1>", self._on_release)
        self.bind("<Enter>", lambda e: self._set_hover(True))
        self.bind("<Leave>", lambda e: self._set_hover(False))
        self.bind("<Configure>", lambda e: self._draw())   # 网格拉伸/首次映射时按实际尺寸重绘

    # ---- 状态 ----
    def _set_hover(self, on):
        self._hover = on
        self._draw()

    def _on_press(self, _event):
        if self._state != "normal":
            return
        self._pressed = True
        self._draw()

    def _on_release(self, event):
        was_inside = self._pressed and 0 <= event.x <= self.winfo_width() and 0 <= event.y <= self.winfo_height()
        self._pressed = False
        self._draw()
        if was_inside and self._state == "normal" and callable(self._command):
            self._command()

    def invoke(self):
        if self._state == "normal" and callable(self._command):
            self._command()

    # ---- 兼容 ttk.Button 的常用接口 ----
    def configure(self, cnf=None, **kw):
        cnf = dict(cnf or {}, **kw)
        if "text" in cnf:
            self._text = str(cnf.pop("text"))
            w = self._font.measure(self._text) + int(32 * self.scale)
            self.configure(width=w)   # tk.Canvas.configure
        if "command" in cnf:
            self._command = cnf.pop("command")
        if "state" in cnf:
            st = cnf.pop("state")
            if st in ("normal", "disabled"):
                if st != self._state:          # 状态切换需重绘（禁用⇄启用画面不同）
                    self._state = st
                    self._hover = self._pressed = False
                    self._draw()
        if cnf:
            super().configure(cnf)

    config = configure

    def cget(self, key):
        if key == "text":
            return self._text
        if key == "state":
            return self._state
        if key == "command":
            return self._command
        return super().cget(key)

    def __getitem__(self, key):
        return self.cget(key)

    # ---- 绘制 ----
    def _draw(self):
        c = self._colors
        if self._state == "disabled":
            bg, fg = c["disabled_bg"], c["disabled_fg"]
        elif self._pressed:
            bg, fg = c["press"], c["fg"]
        elif self._hover:
            bg, fg = c["hover"], c["fg"]
        else:
            bg, fg = c["bg"], c["fg"]
        self.delete("all")
        w = self.winfo_width()
        h = self.winfo_height()
        if w <= 2:
            w = self.winfo_reqwidth()
        if h <= 2:
            h = self.winfo_reqheight()
        r = h // 2
        self.create_polygon(
            r, 1, w - r, 1, w - 1, 1, w - 1, r, w - 1, h - r, w - 1, h - 1, w - r, h - 1,
            r, h - 1, 1, h - 1, 1, h - r, 1, r, 1, 1,
            smooth=True, splinesteps=24, fill=bg, outline=bg)
        self.create_text(w // 2, h // 2, text=self._text, fill=fg,
                         font=self._font, justify="center")


class SquareCheckbox(tk.Canvas):
    """大号方框复选框：白底圆角方框 + 选中蓝底白勾（Canvas 自绘）。

    为什么不用 ttk.Checkbutton：clam 主题的 indicatordiameter 选项在 Tk 8.6.15
    被接受但渲染时忽略（实测 A/B 尺寸不变），指示器只有约 13px，小且像对勾。
    """

    def __init__(self, master, text="", variable=None, command=None,
                 scale=1.0, font=None, **kw):
        self._s = scale
        self._text = text
        self._command = command
        self._var = variable if variable is not None else tk.BooleanVar(value=False)
        self._font = font or (FONT_FAMILY, 10)
        self._hover = False
        self._press = False
        # 方框尺寸：逻辑 18px（明显大于 ttk 默认 ~13px 的"小方框打叉"）
        self._box = max(18, int(18 * scale))
        # 宿主底色：ttk 容器（如 LabelFrame）没有 background 选项
        try:
            host = master.cget("background")
            if not (isinstance(host, str) and host.startswith("#")):
                host = CARD_BG
        except (tk.TclError, AttributeError):
            host = CARD_BG
        super().__init__(master, bg=host, highlightthickness=0, bd=0,
                         takefocus=True, **kw)
        self._sync_size()
        self._var.trace_add("write", lambda *_: self._redraw())
        self.bind("<ButtonPress-1>", self._on_press)
        self.bind("<ButtonRelease-1>", self._on_release)
        self.bind("<Enter>", lambda e: (setattr(self, "_hover", True), self._redraw()))
        self.bind("<Leave>", lambda e: (setattr(self, "_hover", False),
                                        setattr(self, "_press", False), self._redraw()))
        self.bind("<space>", lambda e: self._toggle())
        self.bind("<Destroy>", lambda e: None, add="+")
        self.bind("<Configure>", lambda e: self._redraw())
        self._redraw()

    # ---- 行为 ----
    def _toggle(self):
        self._var.set(not bool(self._var.get()))
        if self._command:
            self._command()

    def _on_press(self, _e):
        self._press = True
        self.focus_set()
        self._redraw()

    def _on_release(self, e):
        was_press = self._press
        self._press = False
        self._redraw()
        if was_press and 0 <= e.x <= self.winfo_width():
            self._toggle()

    def _redraw(self):
        try:
            checked = bool(self._var.get())
            self.delete("all")
        except tk.TclError:                 # 已销毁，trace 回调可能仍触发
            return
        s, b = self._s, self._box
        r = max(3, int(4 * s))              # 圆角半径
        if checked:
            fill, outline = BLUE, BLUE
        elif self._press:
            fill, outline = "#eef5ff", "#7db4f5"
        elif self._hover:
            fill, outline = "#ffffff", "#8fbdf5"
        else:
            fill, outline = "#ffffff", "#b9b9c0"   # 未选：白底灰边，方框清晰可辨
        self.create_polygon(
            r, 1, b - r, 1, b, 1, b, r, b, b - r, b, b, b - r, b, r, b,
            1, b, 1, b - r, 1, r, 1, 1,
            smooth=True, splinesteps=12, fill=fill, outline=outline, width=1)
        if checked:                          # 白勾（圆头粗线）
            lw = max(2, int(2.4 * s))
            self.create_line(b * 0.26, b * 0.54, b * 0.44, b * 0.72, b * 0.76, b * 0.28,
                             fill="#ffffff", width=lw, capstyle="round",
                             joinstyle="round", smooth=True)
        if self._text:
            gap = int(9 * s)
            self.create_text(b + gap, self.winfo_height() // 2, text=self._text,
                             fill=TEXT1, font=self._font, anchor="w")

    # ---- 兼容 ttk.Checkbutton 常用接口 ----
    def configure(self, cnf=None, **kw):
        cnf = dict(cnf or {}, **kw)
        if "text" in cnf:
            self._text = str(cnf.pop("text"))
            self._sync_size()
        if "command" in cnf:
            self._command = cnf.pop("command")
        if "variable" in cnf:
            self._var = cnf.pop("variable")
            self._var.trace_add("write", lambda *_: self._redraw())
        if cnf:
            super().configure(cnf)
        self._redraw()

    config = configure

    def cget(self, key):
        if key == "text":
            return self._text
        if key == "variable":
            return self._var
        if key == "command":
            return self._command
        return super().cget(key)

    def __getitem__(self, key):
        return self.cget(key)

    def _sync_size(self):
        gap = int(9 * self._s)
        tw = self.tk.call("font", "measure", self._font, self._text) if self._text else 0
        th = self.tk.call("font", "metrics", self._font, "-linespace")   # 行高（标量）
        h = max(self._box, int(th)) + 2 * int(4 * self._s)
        super().configure(width=int(self._box + (gap + int(tw) if self._text else 0) + 2),
                          height=int(h))
        self._redraw()

    def invoke(self):
        self._toggle()


def setup_styles(scale):
    """全局 ttk 样式：clam 底座 + Apple 配色。ttk 无法圆角，按钮由 RoundedButton 承担。"""
    style = ttk.Style()
    try:
        style.theme_use("clam")
    except tk.TclError:
        pass
    f_label = (FONT_FAMILY, 10)
    f_small = (FONT_FAMILY, 9)
    # 标签：卡片内默认白底；窗口底上的元素用 Bg.*；次要文本用 Sub.*
    style.configure("TLabel", background=CARD_BG, foreground=TEXT1, font=f_label)
    style.configure("Bg.TLabel", background=WIN_BG, foreground=SIGN_GRAY, font=f_small)
    style.configure("Sub.TLabel", background=CARD_BG, foreground=TEXT2, font=f_label)
    style.configure("BgSub.TLabel", background=WIN_BG, foreground=TEXT2, font=f_label)
    style.configure("BgBody.TLabel", background=WIN_BG, foreground=TEXT1, font=f_label)
    style.configure("BgTitle.TLabel", background=WIN_BG, foreground=TEXT1, font=(FONT_FAMILY, 11, "bold"))
    style.configure("CardTitle.TLabel", background=CARD_BG, foreground=TEXT1, font=(FONT_FAMILY, 11, "bold"))
    style.configure("Tip.TLabel", background=TIP_BG, foreground=TEXT1, font=f_label)
    style.configure("TipTitle.TLabel", background=TIP_BG, foreground=TIP_TEXT, font=(FONT_FAMILY, 10, "bold"))
    style.configure("Hint.TLabel", background=CARD_BG, foreground=TIP_TEXT, font=f_label)
    style.configure("Title.TLabel", background=CARD_BG, foreground=TEXT1, font=(FONT_FAMILY, 11, "bold"))
    style.configure("BgSub.TLabel", background=WIN_BG, foreground=TEXT2, font=f_label)
    # 第二步引导窗：H1 大标题 / H2 小节标题 / 警示条
    style.configure("BgH1.TLabel", background=WIN_BG, foreground=TEXT1, font=(FONT_FAMILY, 16, "bold"))
    style.configure("BgH2.TLabel", background=WIN_BG, foreground=TEXT1, font=(FONT_FAMILY, 13, "bold"))
    style.configure("WarnTitle.TLabel", background=WARN_BG, foreground=WARN_TEXT, font=(FONT_FAMILY, 10, "bold"))
    style.configure("Warn.TLabel", background=WARN_BG, foreground=WARN_TEXT, font=f_label)
    # 启动项预览：等宽字体
    style.configure("Mono.TLabel", background=CARD_BG, foreground=TEXT1, font=("Consolas", 9))
    # Steam 状态卡：粗体状态词（颜色由代码动态设置红/绿）
    style.configure("StateTitle.TLabel", background=CARD_BG, foreground=TEXT1,
                    font=(FONT_FAMILY, 10, "bold"))
    # 写入成功卡（浅绿底）
    style.configure("OkTitle.TLabel", background=CUR_BG, foreground=GREEN_OK,
                    font=(FONT_FAMILY, 13, "bold"))
    style.configure("OkBody.TLabel", background=CUR_BG, foreground=TEXT1, font=f_label)
    # 框架：卡片内默认白底；窗口底用 Bg.TFrame
    style.configure("TFrame", background=CARD_BG)
    style.configure("Bg.TFrame", background=WIN_BG)
    style.configure("Card.TFrame", background=CARD_BG)
    # 输入框：白底细边，聚焦变蓝（键盘焦点可见性）
    style.configure("TEntry", fieldbackground=CARD_BG, foreground=TEXT1,
                    bordercolor=CARD_BORDER, lightcolor=CARD_BORDER, darkcolor=CARD_BORDER,
                    insertcolor=TEXT1, padding=max(2, int(4 * scale)))
    style.map("TEntry",
              bordercolor=[("focus", BLUE)], lightcolor=[("focus", BLUE)], darkcolor=[("focus", BLUE)])
    # 备份对话框里的复选框（clam 底座重配色）
    style.configure("TCheckbutton", background=CARD_BG, foreground=TEXT1, font=f_label, focuscolor=CARD_BG)
    style.map("TCheckbutton", background=[("active", CARD_BG)])
    # 备份对话框的复选框已改为 SquareCheckbox（Canvas 自绘大方框），
    # 因 clam 主题的 indicatordiameter 选项在 Tk 8.6.15 渲染时不生效。
    style.configure("TLabelframe", background=CARD_BG, foreground=TEXT1, bordercolor=CARD_BORDER)
    style.configure("TLabelframe.Label", background=CARD_BG, foreground=TEXT2, font=f_small)
    # 语言列表：去边框、平坦表头、舒适行高、浅蓝选中
    # 行高取 21*scale：比 vista 默认（约 24px 固定）更有呼吸感，又不至于把窗口撑得过高
    style.configure("Treeview", background=CARD_BG, fieldbackground=CARD_BG, foreground=TEXT1,
                    rowheight=max(24, int(21 * scale)), borderwidth=0, relief="flat", font=f_label)
    style.configure("Treeview.Heading", background=CARD_BG, foreground=TEXT2,
                    font=f_small, relief="flat", borderwidth=0, padding=(0, 2))
    style.map("Treeview.Heading", background=[("active", CARD_BG)], foreground=[("active", TEXT2)])
    style.map("Treeview",
              background=[("selected", SELECT_BG)],
              foreground=[("selected", TEXT1)])
    # 滚动条：细、浅灰、无箭头感
    style.configure("TScrollbar", troughcolor=CARD_BG, background="#d3d3d8",
                    bordercolor=CARD_BG, lightcolor=CARD_BG, darkcolor=CARD_BG,
                    arrowcolor="#9a9aa0", gripcount=0, arrowsize=max(10, int(11 * scale)))
    style.map("TScrollbar", background=[("active", "#c2c2c8"), ("pressed", "#b5b5bb")])


class RoundedFrame(tk.Frame):
    """圆角边框分区容器。

    tkinter 原生控件没有圆角，这里用 Canvas 绘制圆角矩形作为背景/边框，
    内容请放进 self.body。expand_content=True 时内容随容器高度拉伸（用于列表/日志）。
    """

    def __init__(self, master, radius=10, padx=12, pady=10, border=CARD_BORDER,
                 expand_content=False, fill=CARD_BG, outside=WIN_BG):
        super().__init__(master, background=outside)
        self.radius = radius
        self.padx, self.pady = padx, pady
        self.border_color = border
        self.bg = fill
        self.expand_content = expand_content
        self.canvas = tk.Canvas(self, background=outside, highlightthickness=0, bd=0)
        self.canvas.pack(fill="both", expand=True)
        self.body = tk.Frame(self.canvas, background=fill)
        self._win = self.canvas.create_window(padx, pady, anchor="nw", window=self.body)
        self.canvas.bind("<Configure>", self._on_canvas_configure)
        self.body.bind("<Configure>", self._on_body_configure)

    def _on_canvas_configure(self, event):
        w, h = event.width, event.height
        self.canvas.delete("bgshape")
        self._draw_round_rect(1, 1, max(2, w - 1), max(2, h - 1), self.radius)
        self.canvas.tag_lower("bgshape")
        self.canvas.itemconfigure(self._win, width=max(1, w - 2 * self.padx))
        if self.expand_content:
            self.canvas.itemconfigure(self._win, height=max(1, h - 2 * self.pady))

    def _on_body_configure(self, event):
        # 始终按内容设置画布的请求高度，避免 Canvas 默认 378x265 把窗口撑大；
        # expand_content=True 时再由 _on_canvas_configure 把内容拉伸到实际高度。
        self.canvas.configure(height=self.body.winfo_reqheight() + 2 * self.pady)

    def sync_size(self):
        """按当前内容同步画布请求高度（内容添加完毕后调用，事件尚未来得及派发时也准确）。"""
        try:
            self.body.update_idletasks()
            self.canvas.configure(height=self.body.winfo_reqheight() + 2 * self.pady)
        except tk.TclError:
            pass

    def _draw_round_rect(self, x1, y1, x2, y2, r):
        pts = [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r,
               x2, y2 - r, x2, y2, x2 - r, y2, x1 + r, y2,
               x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]
        self.canvas.create_polygon(pts, smooth=True, splinesteps=16, width=1,
                                   outline=self.border_color, fill=self.bg, tags="bgshape")


# ---------------------------------------------------------------- GUI

class App:
    def __init__(self, root, scale=1.0):
        self.root = root
        self.scale = scale
        root.title(APP_TITLE)          # 标题栏不显示作者名（署名移至右下角小字 + exe 属性）
        apply_window_icon(root)        # 窗口 + 任务栏图标（内嵌资源）
        # 分辨率自适应：按缩放放大界面，同时不超过屏幕的 90%
        sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
        w = min(int(820 * scale), int(sw * 0.9))
        h = min(int(680 * scale), int(sh * 0.9))
        root.geometry(f"{w}x{h}")
        root.minsize(min(int(740 * scale), int(sw * 0.8)), min(int(600 * scale), int(sh * 0.7)))
        self.cfg = load_app_config()
        self.packs = {}
        self._build_ui()
        self.refresh()
        self._start_watch()   # 每 0.5 秒自动监测启动项状态
        for _s in self._sections:
            _s.sync_size()
        self._fit_window()    # 窗口高度贴合内容（日志区随窗口拉伸）

    def _fit_window(self):
        """按内容自适应窗口高度：不再固定 680，避免语言列表区长期留大片空白。"""
        try:
            self.root.update_idletasks()
            w = self.root.winfo_width()
            if w <= 1:
                w = min(int(820 * self.scale), int(self.root.winfo_screenwidth() * 0.9))
            h = max(int(360 * self.scale), min(self.root.winfo_reqheight(),
                                              int(self.root.winfo_screenheight() * 0.9)))
            self.root.geometry(f"{int(w)}x{int(h)}")
            self.root.minsize(min(int(700 * self.scale), int(self.root.winfo_screenwidth() * 0.8)),
                              int(h * 0.8))
        except tk.TclError:
            pass

    # ---- UI 构建 ----
    def _build_ui(self):
        pad = {"padx": 10, "pady": 5}

        # ──────────────── ① 游戏路径（无标题圆角分区）────────────────
        self._sections = []
        sec1 = RoundedFrame(self.root, radius=int(12 * self.scale))
        self._sections.append(sec1)
        sec1.pack(fill="x", **pad)
        card1 = sec1.body
        self.var_game = tk.StringVar()
        self.var_cfg = tk.StringVar()
        self.var_bak = tk.StringVar()
        for i, (label, var) in enumerate([
            ("游戏目录", self.var_game), ("profile.cfg", self.var_cfg), ("备份库", self.var_bak),
        ]):
            ttk.Label(card1, text=label, width=10, style="Sub.TLabel", anchor="e").grid(
                row=i, column=0, sticky="e", padx=4, pady=3)
            ttk.Entry(card1, textvariable=var).grid(row=i, column=1, sticky="we", padx=4)
            card1.columnconfigure(1, weight=1)
            RoundedButton(card1, text="浏览", scale=self.scale, padding_x=10,
                          command=lambda v=var, i=i: self._browse(v, i)).grid(row=i, column=2, padx=4)
        RoundedButton(card1, text="自动检测 / 刷新", scale=self.scale,
                      command=self.on_detect_refresh).grid(
            row=0, column=3, rowspan=2, padx=(8, 2), pady=3, sticky="ns")
        # 把已检测/已保存的路径填入界面
        self.var_game.set(self.cfg.get("game_dir", ""))
        self.var_cfg.set(self.cfg.get("profile_cfg", ""))
        self.var_bak.set(self.cfg.get("backup_dir", ""))

        # ──────────────── ② 配音语音（无标题圆角分区）────────────────
        sec2 = RoundedFrame(self.root, radius=int(12 * self.scale))
        self._sections.append(sec2)
        sec2.pack(fill="x", **pad)
        card2 = sec2.body

        # 状态行：左侧「当前配音」，右侧「Steam 启动项状态」（颜色随一致性变化）
        status_row = ttk.Frame(card2)
        status_row.pack(fill="x", pady=(0, 6))
        self.var_current = tk.StringVar(value="当前配音：检测中…")
        ttk.Label(status_row, textvariable=self.var_current, style="Title.TLabel").pack(side="left")
        self.var_warn = tk.StringVar(value="")
        self.lbl_warn = ttk.Label(status_row, textvariable=self.var_warn, foreground=TEXT2)
        self.lbl_warn.pack(side="right")

        treef = ttk.Frame(card2)
        treef.pack(fill="both", expand=True, pady=(0, 6))
        self.tree = ttk.Treeview(treef, columns=("name", "status"), show="headings", height=8, selectmode="browse")
        self.tree.heading("name", text="语言")
        self.tree.heading("status", text="语音包状态")
        self.tree.column("name", width=240)
        self.tree.column("status", width=400)
        self.tree.pack(side="left", fill="both", expand=True)
        sb = ttk.Scrollbar(treef, command=self.tree.yview)
        sb.pack(side="right", fill="y")
        self.tree.configure(yscrollcommand=sb.set)

        btns = ttk.Frame(card2)
        btns.pack(fill="x", pady=(8, 0))
        self.btn_switch = RoundedButton(btns, text="切换配音", kind="primary", scale=self.scale,
                                        command=self.on_apply_voice)
        self.btn_switch.pack(side="left", padx=(2, 8))
        for _t, _c in (("启动游戏", self.on_launch), ("备份语音包", self.on_backup_dialog),
                       ("恢复默认", self.on_reset), ("使用指南", self.on_guide)):
            RoundedButton(btns, text=_t, scale=self.scale, command=_c).pack(side="left", padx=4)

        # ──────────────── ③ 日志（无标题圆角分区，随窗口拉伸）────────────────
        sec3 = RoundedFrame(self.root, radius=int(12 * self.scale), expand_content=True)
        self._sections.append(sec3)
        sec3.pack(fill="both", expand=True, **pad)
        self.log = tk.Text(sec3.body, height=6, state="disabled", wrap="word", bd=0,
                           highlightthickness=0, background=CARD_BG, foreground="#3a3a3c",
                           padx=int(6 * self.scale), pady=int(4 * self.scale),
                           spacing1=2, spacing3=2, insertbackground=TEXT1,
                           font=(FONT_FAMILY, 9))
        self.log.pack(fill="both", expand=True)

        # 作者署名（防伪标识，请勿移除）：弱化展示——小字号、浅灰色、右下角单行
        ttk.Label(self.root, text=f"作者：{AUTHOR} v{APP_VERSION}",
                  style="Bg.TLabel", anchor="e").pack(
            fill="x", padx=12, pady=(0, int(4 * self.scale)))

        # 防伪自检（启动即校验）：标记被抹改的程序会在此提示非官方版本
        if not verify_anti_fake():
            self._log("⚠ 防伪标记校验失败：这可能不是官方版本（官方作者：北冥若曦 · 蝶梦影）")

    def _set_modal_lock(self, locked):
        """二级窗口打开期间锁定主窗口：禁止拖动/点击/缩放，关闭后自动恢复。

        Windows 下用 -disabled 属性实现（主窗口标题栏变灰且无法拖动）。
        """
        try:
            self.root.attributes("-disabled", bool(locked))
        except (tk.TclError, AttributeError):
            pass

    def _browse(self, var, kind):
        if kind == 0:
            p = filedialog.askdirectory(
                title="选择 Apex 目录（填游戏根目录 / audio / audio\\ship 都可以）")
        elif kind == 1:
            p = filedialog.askopenfilename(title="选择 profile.cfg", filetypes=[("cfg", "*.cfg"), ("全部", "*.*")])
        else:
            p = filedialog.askdirectory(title="选择语音包备份库目录")
        if p:
            var.set(p)
            self._save_paths()

    def _save_paths(self):
        """保存路径；游戏目录自动归一化为游戏根目录（兼容用户填 audio\\ship 的情况）。"""
        gd = self.var_game.get().strip()
        if gd and os.path.isdir(gd):
            root_dir = guess_game_root(gd)
            if root_dir and os.path.isdir(os.path.join(root_dir, "audio", "ship")) and root_dir != os.path.normpath(gd):
                self.var_game.set(root_dir)
        self.cfg.update({"game_dir": self.var_game.get(), "profile_cfg": self.var_cfg.get(), "backup_dir": self.var_bak.get()})
        save_app_config(self.cfg)

    # ---- 工具 ----
    def _log(self, msg):
        self.log.configure(state="normal")
        self.log.insert("end", msg + "\n")
        self.log.see("end")
        self.log.configure(state="disabled")

    def _safe(self, fn, *args, ok_msg=""):
        try:
            r = fn(*args)
            if ok_msg:
                self._log(ok_msg)
            return r
        except Exception as e:  # noqa: BLE001
            messagebox.showerror(APP_TITLE, f"操作失败：{e}")
            return None

    # ---- 动作 ----
    def refresh(self):
        self._save_paths()
        self.packs = scan_installed_packs(self.var_game.get())
        backups = scan_backup_packs(self.var_bak.get())
        current = get_current_voice(self.var_cfg.get())

        # 路径填法异常时给出可操作的提示（避免再次出现「备份 0 个」的困惑）
        gd = self.var_game.get()
        hint = ""
        if gd and os.path.isdir(gd):
            sd = ship_dir(gd)
            if not self.packs:
                hint = (f"⚠ 未在 {sd} 找到语音包文件。请把「游戏目录」指向 Apex 根目录"
                        f"（即包含 audio\\ship 的那一层）。")
        elif gd:
            hint = f"⚠ 游戏目录不存在：{gd}"
        if hint and hint != getattr(self, "_last_hint", ""):
            self._log(hint)
        self._last_hint = hint

        # 启动项与当前设置的一致性检查（每 0.5 秒自动监测，见 _update_pin_status）
        self._update_pin_status()

        self.tree.delete(*self.tree.get_children())
        langs = sorted(set(self.packs) | set(backups))
        for lang in langs:
            n = len(self.packs.get(lang, []))
            if n:
                size = sum(os.path.getsize(f) for f in self.packs[lang]) / 1024 / 1024 / 1024
                status = f"✓ 已就绪（{n} 个文件，共 {size:.1f} GB）"
            elif backups.get(lang):
                status = "◐ 游戏目录缺失，可从备份库一键恢复"
            else:
                status = "✗ 缺失（见「使用指南」获取方法）"
            tag = "cur" if lang == current else ("no" if n == 0 else "ok")
            self.tree.insert("", "end", iid=lang, values=(lang_display(lang), status), tags=(tag,))
        self.tree.tag_configure("cur", background=CUR_BG, foreground=TEXT1)
        self.tree.tag_configure("no", foreground=TEXT3)

        if current:
            self.var_current.set(f"当前配音：{lang_display(current)}")
        elif has_empty_voice_setting(self.var_cfg.get()):
            self.var_current.set('当前配音：⚠ 配置存在空值 miles_language ""（删掉启动项后会生效并可能导致配音异常）'
                                 "——点「切换配音」或「恢复默认」即可修复")
        else:
            self.var_current.set("当前配音：未设置（跟随界面语言，中文 UI 即中文配音）")

    # ---- 启动项状态自动监测（0.5 秒一次）----
    PIN_POLL_MS = 500

    def _start_watch(self):
        self._watch_alive = True
        self.root.after(self.PIN_POLL_MS, self._watch_tick)

    def _watch_tick(self):
        if not getattr(self, "_watch_alive", False):
            return
        try:
            self._update_pin_status()
            self.root.after(self.PIN_POLL_MS, self._watch_tick)
        except tk.TclError:
            return

    def _update_pin_status(self):
        """刷新 ② 区状态行右侧的「Steam 启动项」提示（紧凑写法，详细说明只在状态变化时写日志）。"""
        pinned, ok = _read_pinned_languages_detailed()
        if not ok:
            return  # 配置暂时读不到（Steam 正在重写）→ 保持上次显示，避免闪烁
        try:
            current = get_current_voice(self.var_cfg.get())
        except OSError:
            return
        detail = None
        if pinned:
            names = "、".join(lang_display(x) for x in sorted(pinned))
            if len(pinned) == 1 and current == next(iter(pinned)):
                short, color = f"启动项：{names}（与当前一致）", GREEN_OK
            else:
                cur_name = lang_display(current) if current else "未设置"
                short, color = f"启动项：{names} ≠ 当前 {cur_name}", RED_ERR
                detail = (f"⚠ Steam 启动项固定为「{names}」，与当前设置（{cur_name}）不一致——从 Steam 库启动时"
                          "会用启动项的语言。要统一：选中目标语言 → 点「切换配音」→ 在弹窗中退出 Steam 后写入。")
        else:
            short, color = "启动项：未固定（从 Steam 库启动时用界面语言）", TEXT2

        self.var_warn.set(short)
        self.lbl_warn.configure(foreground=color)
        if detail and detail != getattr(self, "_last_pin_detail", ""):
            self._log(detail)          # 只在状态变化时写一次，不刷屏
        self._last_pin_detail = detail or ""

    def on_reset(self):
        self._save_paths()
        ok, msg = remove_miles_language(self.var_cfg.get())
        (self._log(msg), self.refresh()) if ok else messagebox.showwarning(APP_TITLE, msg)

    def on_launch(self):
        """带所选配音启动游戏（最可靠的生效方式：配音语言在启动时读取）。"""
        sel = self.tree.selection()
        lang = sel[0] if sel else None
        if lang and not self.packs.get(lang):
            messagebox.showwarning(APP_TITLE, f"{lang_display(lang)} 的语音包不在游戏目录中，"
                                              "启动后该配音可能不生效。")
        try:
            msg = launch_game(lang)
        except Exception as e:  # noqa: BLE001
            messagebox.showerror(APP_TITLE,
                                 f"启动失败：{e}\n\n"
                                 "可以手动打开 Steam 启动 Apex，或点「切换配音（并引导写入启动项）」设置固定配音。")
            self._log(f"✗ 启动失败：{e}")
            return
        if not lang:
            self._log("提示：未在列表中选择语言，将按默认语言启动。选中语言后再点此按钮可指定配音。")
        self._log("▶ " + msg)

    def on_apply_voice(self):
        """一键：① 切换配音（写配置文件）→ ② 弹窗引导写入 Steam 启动项。"""
        sel = self.tree.selection()
        if not sel:
            messagebox.showinfo(APP_TITLE, "请先在列表中选中一个语言。")
            return
        lang = sel[0]

        # 语音包缺失时先尝试从备份库恢复
        if not self.packs.get(lang):
            backs = scan_backup_packs(self.var_bak.get()).get(lang, [])
            if backs:
                if messagebox.askyesno(APP_TITLE, f"{lang_display(lang)} 的语音包在游戏目录缺失，\n"
                                                  f"检测到备份库中有 {len(backs)} 个文件，是否自动恢复？"):
                    self._save_paths()
                    n = restore_pack_from_backup(lang, self.var_game.get(), self.var_bak.get())
                    self._log(f"已从备份库恢复 {lang_display(lang)} 的 {n} 个语音包文件。")
            else:
                self._show_guide(lang)
                return

        # 第一步：切换配音（配置文件）
        self._save_paths()
        ok, msg = set_miles_language(self.var_cfg.get(), lang)
        if not ok:
            messagebox.showwarning(APP_TITLE, msg)
            self._log("✗ " + msg)
            return
        self._log(msg)
        self._log(f"✔ 第一步完成：配音已设为「{lang_display(lang)}」。")
        self.refresh()

        # 第二步：Steam 已完全退出 → 直接写入启动项（不弹窗）；仍在运行 → 弹窗引导
        if is_steam_running():
            self._log("检测到 Steam 仍在运行，弹出第二步窗口（退出 Steam 后可一键写入启动项）。")
            SteamOptionDialog(self.root, self, lang)
        else:
            self._log("检测到 Steam 已完全退出 → 自动写入 Steam 启动项…")
            ok, msg = set_steam_launch_option(lang)
            self._log(("✔ " if ok else "✗ ") + msg)
            if ok:
                self._log("第二步已完成（无需任何额外操作），下次从 Steam 启动即为该配音。")
                self.refresh()
            else:
                messagebox.showwarning(APP_TITLE, msg + "\n\n可稍后在 Steam 退出时重试「切换配音（并引导写入启动项）」。")
                SteamOptionDialog(self.root, self, lang)

    def on_detect_refresh(self):
        """合并按钮「自动检测 / 刷新」：先自动检测（仅在路径缺失或失效时回填），再刷新状态。

        设计要点：不会覆盖你手动填写的**有效**路径，因此既能自动修复失效路径，
        也不会把自定义路径改掉。
        """
        changed = []
        gd_now = self.var_game.get().strip()
        gd_ok = bool(gd_now) and os.path.isdir(ship_dir(gd_now))
        cfg_now = self.var_cfg.get().strip()
        cfg_ok = bool(cfg_now) and os.path.isfile(cfg_now)

        if not gd_ok:
            gd = detect_game_dir()
            if gd:
                self.var_game.set(gd)
                changed.append(f"游戏目录 → {gd}")
            else:
                self._log("未能自动识别游戏目录（Steam 库中未找到 Apex Legends），请用「浏览」手动选择。")
        if not cfg_ok:
            cfgp = detect_profile_cfg()
            if cfgp:
                self.var_cfg.set(cfgp)
                changed.append(f"profile.cfg → {cfgp}")
            else:
                self._log("未能自动识别 profile.cfg，请用「浏览」手动选择。")

        if changed:
            self._log("已自动检测并回填：" + "；".join(changed))
        else:
            self._log("路径有效，未做改动（自动检测只在路径缺失/失效时回填）。")

        self.refresh()
        self._log("状态已刷新。")

    def on_backup_dialog(self):
        """弹出勾选界面，选择要备份的语音包。"""
        self._save_paths()
        packs = scan_installed_packs(self.var_game.get())
        if not packs:
            messagebox.showwarning(
                APP_TITLE,
                "未检测到任何语音包文件。\n\n"
                "请确认「游戏目录」指向 Apex 根目录（包含 audio\\ship 的那一层），\n"
                f"当前填写的路径是：\n{self.var_game.get()}",
            )
            return
        BackupDialog(self.root, self)

    def _show_guide(self, lang=None):
        """打开「使用指南」窗口（分步卡片式；lang 参数保留兼容旧调用，暂不区分展示）。"""
        GuideDialog(self.root, self)

    def on_guide(self):
        self._show_guide()


class BackupDialog(tk.Toplevel):
    """备份语音包：勾选要备份的语言，支持高 DPI 缩放，复制在后台线程执行。"""

    def __init__(self, master, app):
        super().__init__(master)
        self.app = app
        self.scale = getattr(app, "scale", 1.0)
        self.title("选择要备份的语音包")
        self.transient(master)
        self.resizable(True, True)
        self.minsize(int(560 * self.scale), int(420 * self.scale))
        self.geometry(f"{int(660 * self.scale)}x{int(560 * self.scale)}")
        self._alive = True
        self.configure(background=WIN_BG)
        app._set_modal_lock(True)              # 锁住主窗口，关闭本窗口后自动恢复
        self.after(80, self._take_grab)
        self.protocol("WM_DELETE_WINDOW", self.destroy)   # 点右上角 × 也要正确解锁主窗口

        self.game_dir = app.var_game.get()
        self.backup_dir = app.var_bak.get()
        self.packs = scan_installed_packs(self.game_dir)
        self.vars = {}
        self.q = queue.Queue()
        self.running = False

        s = self.scale
        outer = ttk.Frame(self, style="Bg.TFrame", padding=int(10 * s))
        outer.pack(fill="both", expand=True)

        ttk.Label(outer, text="已检测到的语音包（勾选后点「开始备份」）",
                  style="BgTitle.TLabel").pack(anchor="w")
        ttk.Label(outer, text=f"来源：{ship_dir(self.game_dir)}",
                  style="BgSub.TLabel", wraplength=int(600 * s)).pack(anchor="w", pady=(2, int(8 * s)))

        listf = ttk.LabelFrame(outer, text="语音包")
        listf.pack(fill="both", expand=True)
        backed = scan_backup_packs(self.backup_dir)
        # 三列 grid 对齐：语言名 | 文件数与大小 | 备份库状态——各占一列，多行整齐不参差
        listf.columnconfigure(1, weight=1)
        rowi = 0
        for lang in sorted(self.packs):
            files = self.packs[lang]
            size = sum(os.path.getsize(f) for f in files) / 1024 / 1024 / 1024
            already = len(backed.get(lang, []))
            var = tk.BooleanVar(value=True)
            self.vars[lang] = var
            pady = int(4 * s)
            SquareCheckbox(listf, text=f"{lang_display(lang)}（{lang}）",
                           variable=var, scale=s).grid(
                row=rowi, column=0, sticky="w", padx=(int(10 * s), int(16 * s)), pady=pady)
            ttk.Label(listf, text=f"{len(files)} 个文件 · {size:.2f} GB",
                      style="Sub.TLabel").grid(
                row=rowi, column=1, sticky="w", padx=(0, int(16 * s)), pady=pady)
            if already:
                ttk.Label(listf, text=f"备份库已有 {already} 个，将跳过",
                          style="Hint.TLabel").grid(
                    row=rowi, column=2, sticky="w", padx=(0, int(10 * s)), pady=pady)
            rowi += 1

        row = ttk.Frame(outer, style="Bg.TFrame")
        row.pack(fill="x", pady=(int(8 * s), 0))
        RoundedButton(row, text="全选", scale=s, padding_x=12, command=lambda: self._set_all(True)).pack(
            side="left", padx=3)
        RoundedButton(row, text="全不选", scale=s, padding_x=12, command=lambda: self._set_all(False)).pack(
            side="left", padx=3)
        RoundedButton(row, text="更改备份位置", scale=s, command=self._change_dir).pack(side="left", padx=8)

        self.var_target = tk.StringVar(value=f"备份到：{self.backup_dir}")
        ttk.Label(outer, textvariable=self.var_target, wraplength=int(600 * s),
                  style="BgSub.TLabel").pack(anchor="w", pady=(int(6 * s), 0))

        self.var_prog = tk.StringVar(value="")
        ttk.Label(outer, textvariable=self.var_prog, style="BgBody.TLabel").pack(anchor="w", pady=(int(4 * s), 0))

        btns = ttk.Frame(outer, style="Bg.TFrame")
        btns.pack(fill="x", pady=(int(8 * s), 0))
        self.btn_start = RoundedButton(btns, text="开始备份", kind="primary", scale=s, command=self._start)
        self.btn_start.pack(side="left")
        RoundedButton(btns, text="关闭", scale=s, command=self.destroy).pack(side="right")

        self._center_on(master)

    # ---- 模态与解锁 ----
    def _take_grab(self):
        """把输入焦点独占给本窗口（模态）；窗口未就绪时静默跳过。"""
        if not self._alive:
            return
        try:
            self.grab_set()
        except tk.TclError:
            pass

    def destroy(self):
        self._alive = False
        try:
            self.grab_release()
        except tk.TclError:
            pass
        self.app._set_modal_lock(False)        # 恢复主窗口可拖动
        super().destroy()

    # ---- 内部 ----
    def _center_on(self, master):
        try:
            master.update_idletasks()
            x = master.winfo_rootx() + (master.winfo_width() - self.winfo_reqwidth()) // 2
            y = master.winfo_rooty() + int(60 * self.scale)
            self.geometry(f"+{max(0, x)}+{max(0, y)}")
        except tk.TclError:
            pass

    def _set_all(self, value):
        for v in self.vars.values():
            v.set(value)

    def _change_dir(self):
        p = filedialog.askdirectory(title="选择语音包备份库目录", parent=self)
        if p:
            self.backup_dir = p
            self.app.var_bak.set(p)
            self.app._save_paths()
            self.var_target.set(f"备份到：{p}")

    def _poll_guard(self):
        return getattr(self, "_alive", True)

    def _start(self):
        langs = {lang for lang, v in self.vars.items() if v.get()}
        if not langs:
            messagebox.showinfo(APP_TITLE, "请至少勾选一个语音包。", parent=self)
            return
        need = selected_size(self.game_dir, langs)
        try:
            free = shutil.disk_usage(self.backup_dir).free
            if free < need:
                if not messagebox.askyesno(
                        APP_TITLE,
                        f"备份库所在磁盘可用空间不足：\n需要约 {need / 1024 / 1024 / 1024:.1f} GB，"
                        f"可用 {free / 1024 / 1024 / 1024:.1f} GB。\n\n仍要继续吗？", parent=self):
                    return
        except OSError:
            pass
        self.running = True
        self.btn_start.config(state="disabled")
        threading.Thread(target=self._worker, args=(langs,), daemon=True).start()
        self.after(150, self._poll)

    def _worker(self, langs):
        try:
            copied, skipped, failed, total = export_packs_to_backup(
                self.game_dir, self.backup_dir, langs, progress=self.q.put)
            self.q.put(("__done__", (copied, skipped, failed, total)))
        except Exception as e:  # noqa: BLE001
            self.q.put(("__error__", str(e)))

    def _poll(self):
        if not self._poll_guard():
            return  # 窗口已关闭：停止回显，后台复制线程自行结束
        try:
            while True:
                item = self.q.get_nowait()
                if isinstance(item, tuple):
                    kind, payload = item
                    if kind == "__done__":
                        copied, skipped, failed, total = payload
                        self.var_prog.set(f"完成：新备份 {len(copied)} 个，跳过 {len(skipped)} 个，"
                                          f"失败 {len(failed)} 个，共 {total / 1024 / 1024 / 1024:.2f} GB")
                        self.app._log(f"备份完成：新备份 {len(copied)} 个，跳过 {len(skipped)} 个，"
                                      f"失败 {len(failed)} 个，共 {total / 1024 / 1024 / 1024:.2f} GB → {self.backup_dir}")
                        for f in failed:
                            self.app._log(f"  ✗ {f}")
                        self.running = False
                        self.btn_start.config(state="normal")
                        self.app.refresh()
                        return
                    if kind == "__error__":
                        messagebox.showerror(APP_TITLE, f"备份失败：{payload}", parent=self)
                        self.running = False
                        self.btn_start.config(state="normal")
                        return
                else:
                    self.var_prog.set(str(item))
                    self.app._log(f"  {item}")
        except queue.Empty:
            pass
        if self.running:
            self.after(200, self._poll)


class SteamOptionDialog(tk.Toplevel):
    """第二步引导：把配音参数写入 Steam 启动项（需先完全退出 Steam）。"""

    def __init__(self, master, app, lang):
        super().__init__(master)
        self.app = app
        self.lang = lang
